#include <bits/stdc++.h>
using namespace std;

string longestPalindromeSubseq(string s) {
    int n = s.size();
    vector<vector<string>> dp(n, vector<string>(n));

    // Base case: single character is not considered palindrome (length < 3)
    for (int i = 0; i < n; i++) {
        dp[i][i] = "";
    }

    // Base case: two characters
    for (int i = 0; i < n - 1; i++) {
        if (s[i] == s[i + 1]) {
            dp[i][i + 1] = "";
        } else {
            dp[i][i + 1] = "";
        }
    }

    // Fill DP table
    for (int len = 3; len <= n; len++) {
        for (int i = 0; i <= n - len; i++) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                string mid = dp[i + 1][j - 1];
                if (mid != "" || (i + 1 > j - 1)) {
                    dp[i][j] = s[i] + mid + s[j];
                } else {
                    dp[i][j] = "";
                }
            } else {
                dp[i][j] = "";
            }
            // Also consider the longer of the two subproblems
            string left = dp[i][j - 1];
            string down = dp[i + 1][j];
            if (dp[i][j].size() < left.size()) dp[i][j] = left;
            if (dp[i][j].size() < down.size()) dp[i][j] = down;
        }
    }

    return dp[0][n - 1];
}

