/*
Longest Palindromic Subsequence, with reconstruction.
Strings are uppercase, length <= 2000.
Input: multiple datasets, one string per dataset, until EOF.
Output: one longest palindromic subsequence per line.

DP:
dp[i][j] = length of LPS in s[i..j]
Transition:
- if s[i] == s[j]: dp[i][j] = dp[i+1][j-1] + 2
- else dp[i][j] = max(dp[i+1][j], dp[i][j-1])

Reconstruction:
walk from (0, n-1), building left/right halves.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (cin >> s) {
        int n = (int)s.size();
        if (n == 0) {
            cout << "\n";
            continue;
        }

        vector<vector<unsigned short>> dp(n, vector<unsigned short>(n, 0));

        for (int i = 0; i < n; ++i) dp[i][i] = 1;

        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len - 1 < n; ++i) {
                int j = i + len - 1;
                if (s[i] == s[j]) {
                    dp[i][j] = (len == 2 ? 2 : (unsigned short)(dp[i + 1][j - 1] + 2));
                } else {
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
                }
            }
        }

        int L = dp[0][n - 1];
        string left, right;
        left.reserve((L + 1) / 2);
        right.reserve(L / 2);

        int i = 0, j = n - 1;
        while (i <= j) {
            if (i == j) {
                if (dp[i][j] == 1) left.push_back(s[i]);
                break;
            }

            if (s[i] == s[j]) {
                unsigned short inside = (i + 1 <= j - 1 ? dp[i + 1][j - 1] : 0);
                if (dp[i][j] == inside + 2) {
                    left.push_back(s[i]);
                    right.push_back(s[j]);
                    ++i;
                    --j;
                    continue;
                }
            }

            if (dp[i + 1][j] >= dp[i][j - 1]) ++i;
            else --j;
        }

        reverse(right.begin(), right.end());
        cout << left << right << '\n';
    }

    return 0;
}

