                if (s[i] == s[j]) {
                    dp[i][j] = dp[i + 1][j - 1] + 2;
                } else {
                    dp[i][j] = dp[i + 1][j] > dp[i][j - 1] ? dp[i + 1][j] : dp[i][j - 1];
                }
            }
        }

        int maxLen = dp[0][n - 1];
        if (maxLen < 3) {
            printf("none\n");
            continue;
        }

        // Reconstruct one longest palindrome subsequence
        char result[MAX + 1];
        int idx = 0;
        int i = 0, j = n - 1;

        while (i <= j) {
            if (i == j && dp[i][j] == 1) {
                result[idx++] = s[i];
                break;
            }
            if (s[i] == s[j]) {
                result[idx++] = s[i];
                i++;
                j--;
            } else if (dp[i][j] == dp[i + 1][j]) {
                i++;
            } else {
                j--;
            }
        }

        // Build the full palindrome
        int mid = idx;
        if (dp[0][n - 1] % 2 == 0) {
            // even length: mirror first half
            for (int k = 0; k < idx; k++)
                result[mid + k] = result[idx - 1 - k];
            result[mid + idx] = '\0';
        } else {
            // odd length: mirror excluding middle character
            for (int k = 0; k < idx - 1; k++)
                result[mid + k] = result[idx - 2 - k];
            result[mid + idx - 1] = '\0';
        }

        printf("%s\n", result);
    }
    return 0;
}

