import sys

def longest_palindrome_subsequence(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the palindrome subsequence
    i, j = 0, n - 1
    left, right = [], []
    while i <= j:
        if s[i] == s[j]:
            left.append(s[i])
            if i != j:
                right.append(s[j])
            i += 1
            j -= 1
        elif dp[i+1][j] > dp[i][j-1]:
            i += 1
        else:
            j -= 1

    palindrome = ''.join(left) + ''.join(reversed(right))

    # If palindrome length <= 2, return empty string (invalid)
    if len(palindrome) <= 2:
        return ""
    return palindrome

