import sys

def lps_string(s: str) -> str:
    n = len(s)
    if n < 3:
        return ""

    # dp[i][j] = length of longest palindromic subsequence in s[i..j]
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                a = dp[i + 1][j]
                b = dp[i][j - 1]
                dp[i][j] = a if a >= b else b

    if dp[0][n - 1] < 3:
        return ""

    # Reconstruct one longest palindromic subsequence
    i, j = 0, n - 1
    left = []
    right = []

    while i <= j:
        if i == j:
            if dp[i][j] == 1:
                left.append(s[i])
            break

        if s[i] == s[j]:
            expected = 2 if i + 1 > j - 1 else dp[i + 1][j - 1] + 2
            if dp[i][j] == expected:
                left.append(s[i])
                right.append(s[j])
                i += 1
                j -= 1
                continue

        if dp[i + 1][j] >= dp[i][j - 1]:
            i += 1
        else:
            j -= 1

    return ''.join(left + right[::-1])

