        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String s = sc.nextLine();
            System.out.println(longestPalindromeSubseq(s));
        }
        sc.close();
    }

    private static String longestPalindromeSubseq(String s) {
        int n = s.length();
        if (n < 3) return "";

        int[][] dp = new int[n][n];
        String[][] pal = new String[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
            pal[i][i] = String.valueOf(s.charAt(i));
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    if (len == 2) {
                        dp[i][j] = 2;
                        pal[i][j] = "" + s.charAt(i) + s.charAt(j);
                    } else {
                        dp[i][j] = dp[i + 1][j - 1] + 2;
                        pal[i][j] = s.charAt(i) + pal[i + 1][j - 1] + s.charAt(j);
                    }
                } else {
                    if (dp[i + 1][j] > dp[i][j - 1]) {
                        dp[i][j] = dp[i + 1][j];
                        pal[i][j] = pal[i + 1][j];
                    } else {
                        dp[i][j] = dp[i][j - 1];
                        pal[i][j] = pal[i][j - 1];
                    }
                }
            }
        }

        String result = pal[0][n - 1];
        return (result.length() >= 3) ? result : "";
    }
}

