public class Main {
    static char[] s;
    static int[][] dp;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            s = line.toCharArray();
            int n = s.length;
            dp = new int[n][n];

            // Fill DP
            for (int i = 0; i < n; i++) dp[i][i] = 1;
            for (int len = 2; len <= n; len++) {
                for (int i = 0; i <= n - len; i++) {
                    int j = i + len - 1;
                    if (s[i] == s[j]) {
                        dp[i][j] = (len == 2) ? 2 : dp[i+1][j-1] + 2;
                    } else {
                        dp[i][j] = Math.max(dp[i+1][j], dp[i][j-1]);
                    }
                }
            }

            int lpsLen = dp[0][n-1];
            if (lpsLen < 3) {
                // No palindrome of length >= 3
                System.out.println("");
                continue;
            }

            // Reconstruct
            String result = reconstruct(0, n-1);
            System.out.println(result);
        }
    }

    static String reconstruct(int i, int j) {
        if (i > j) return "";
        if (i == j) return "" + s[i];
        if (s[i] == s[j]) {
            String mid = reconstruct(i+1, j-1);
            return s[i] + mid + s[j];
        } else {
            if (dp[i+1][j] > dp[i][j-1]) {
                return reconstruct(i+1, j);
            } else {
                return reconstruct(i, j-1);
            }
        }
    }
}

