    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.nextLine();
        if (first == null) return;
        first = first.trim();
        if (first.isEmpty()) return;

        int t = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 0; tc < t; tc++) {
            String s = fs.nextLine();
            while (s != null && s.isEmpty()) s = fs.nextLine();
            if (s == null) s = "";
            String ans = longestPalSubseq(s);
            out.append(ans);
            if (tc + 1 < t) out.append('\n');
        }

        System.out.print(out.toString());
    }

    static String longestPalSubseq(String s) {
        int n = s.length();
        if (n == 0) return "";

        char[] a = s.toCharArray();

        // dp[i][j] = length of LPS in substring [i..j]
        short[][] dp = new short[n][n];

        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                if (a[i] == a[j]) {
                    dp[i][j] = (short) (2 + (i + 1 <= j - 1 ? dp[i + 1][j - 1] : 0));
                } else {
                    dp[i][j] = (short) Math.max(dp[i + 1][j], dp[i][j - 1]);
                }
            }
        }

        int len = dp[0][n - 1];
        char[] res = new char[len];
        int left = 0, right = len - 1;
        int i = 0, j = n - 1;

        while (i <= j) {
            if (i == j) {
                res[left] = a[i];
                break;
            }
            if (a[i] == a[j] && dp[i][j] == (short)(2 + (i + 1 <= j - 1 ? dp[i + 1][j - 1] : 0))) {
                res[left++] = a[i];
                res[right--] = a[j];
                i++;
                j--;
            } else if (dp[i + 1][j] >= dp[i][j - 1]) {
                i++;
            } else {
                j--;
            }
        }

        return new String(res);
    }
